class Solution {
public:
    vector<vector<char>> finalGrid(vector<vector<char>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        for (int step = 0; step < m; ++step) {

            // Step 1: Find bombs that explode.
            vector<vector<bool>> destroy(m, vector<bool>(n, false));

            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] != '*')
                        continue;

                    bool explode = false;

                    const int dr[4] = {-1, 1, 0, 0};
                    const int dc[4] = {0, 0, -1, 1};

                    for (int d = 0; d < 4; ++d) {
                        int x = i + dr[d];
                        int y = j + dc[d];

                        if (x >= 0 && x < m &&
                            y >= 0 && y < n &&
                            grid[x][y] == '#') {
                            explode = true;
                            break;
                        }
                    }

                    if (!explode)
                        continue;

                    // Destroy boxes in all 8 neighboring cells.
                    for (int dx = -1; dx <= 1; ++dx) {
                        for (int dy = -1; dy <= 1; ++dy) {
                            int x = i + dx;
                            int y = j + dy;

                            if (x >= 0 && x < m &&
                                y >= 0 && y < n &&
                                grid[x][y] == '#') {
                                destroy[x][y] = true;
                            }
                        }
                    }
                }
            }

            bool changed = false;

            // Apply all explosions simultaneously.
            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (destroy[i][j]) {
                        grid[i][j] = '-';
                        changed = true;
                    }
                }
            }

            // Step 2: Apply gravity.
            // Bottom-up ensures boxes fall only one row.
            for (int j = 0; j < n; ++j) {
                for (int i = m - 2; i >= 0; --i) {
                    if (grid[i][j] == '#' &&
                        grid[i + 1][j] == '-') {

                        swap(grid[i][j], grid[i + 1][j]);
                        changed = true;
                    }
                }
            }

            if (!changed)
                break;
        }

        return grid;
    }
};
